const ProductPolish={
 t:(cn,en)=>CobaltUI.t(cn,en),
 nav(){window.UnifiedNavigation?.refresh();},
 card(label,value){return '<article class="v34-kpi"><span>'+esc(label)+'</span><strong>'+esc(value??'—')+'</strong></article>';},
 async customers(saved){
  const S=CobaltSalesUI,t=this.t,q=new URLSearchParams(location.search),[rows,contracts,o]=await Promise.all([API.request(S.base+'/customers'),API.request(S.base+'/contracts'),API.request(S.base+'/options')]);S.customerRows=rows.items;S.contractRows=contracts.items;
  const editor=q.get('editor'),id=q.get('id');if(editor){const row=id?(editor==='customer'?rows.items:contracts.items).find(x=>x.id===id):{};if(!row||!['customer','contract'].includes(editor))throw Error(t('记录不存在或无权访问','Record not found or outside your scope'));return this.customerEditor(editor,row,o,saved);}
  const search=(q.get('search')||'').toLowerCase(),validity=q.get('validity')||'',today=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Lubumbashi',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),state=k=>!k.active?'INACTIVE':k.effective_date>today?'UPCOMING':k.end_date<today?'EXPIRED':'VALID',names={VALID:t('有效期内','Valid'),UPCOMING:t('尚未生效','Upcoming'),EXPIRED:t('已到期','Expired'),INACTIVE:t('已停用','Inactive')},visible=contracts.items.filter(k=>(!search||(k.contract_no+' '+k.customer_name).toLowerCase().includes(search))&&(!validity||state(k)===validity)),write=S.can('customer:write');
  S.page(t('客户管理','Customer Management'),`<div class="business-toolbar"><button id="customer-new" class="button primary" ${write?'':'disabled'}>${t('新增客户','Create Customer')}</button><button id="contract-new" class="button secondary" ${write?'':'disabled'}>${t('新增合同','Create Contract')}</button></div><form id="contract-filter" class="business-toolbar filters"><label>${t('搜索合同号 / 客户','Search Contract / Customer')}<input name="search" value="${esc(q.get('search')||'')}"></label><label>${t('有效期状态','Validity')}<select name="validity"><option value="">${t('全部','All')}</option>${Object.entries(names).map(([k,v])=>`<option value="${k}" ${validity===k?'selected':''}>${v}</option>`).join('')}</select></label><button class="button secondary">${t('筛选','Filter')}</button></form><h3>${t('客户档案','Customer Records')}</h3>${S.table([['客户名称','Customer Name'],['客户代码','Customer Code'],['客户地址','Customer Address'],['客户邮箱','Customer Email'],['客户联系方式','Contact Details'],['档案创建日期','Created Date'],['状态','Status'],['操作','Actions']],rows.items.map(c=>`<tr><td data-no-i18n>${esc(c.name)}</td><td data-no-i18n>${esc(c.code)}</td><td data-no-i18n>${esc(c.address||'—')}</td><td data-no-i18n>${esc(c.email||'—')}</td><td data-no-i18n>${esc(c.phone||'—')}</td><td>${ArchiveDate(c.created_at)}</td><td>${t(c.active?'启用':'停用',c.active?'Active':'Inactive')}</td><td><button data-customer-edit="${c.id}" class="button secondary compact" ${write?'':'disabled'}>${t('编辑','Edit')}</button></td></tr>`),'co-sales-customers')}<h3>${t('合同档案（一客户多合同）','Contracts (Multiple Contracts per Customer)')}</h3>${S.table([['合同号','Contract'],['客户名称','Customer Name'],['生效日期','Effective Date'],['截止日期','End Date'],['合同创建日期','Created Date'],['启停状态','Active Status'],['有效期状态','Validity'],['操作','Actions']],visible.map(k=>`<tr><td data-no-i18n>${esc(k.contract_no)}</td><td data-no-i18n>${esc(k.customer_name)}</td><td>${esc(k.effective_date)}</td><td>${esc(k.end_date)}</td><td>${ArchiveDate(k.created_at)}</td><td>${t(k.active?'启用':'停用',k.active?'Active':'Inactive')}</td><td>${names[state(k)]}</td><td><a class="button secondary compact" href="/customers?editor=contract&id=${k.id}">${t(write?'编辑':'查看',write?'Edit':'View')}</a></td></tr>`),'co-sales-contracts')}`);
  $('customer-new').onclick=()=>Router.go('/customers?editor=customer');$('contract-new').onclick=()=>Router.go('/customers?editor=contract');for(const b of document.querySelectorAll('[data-customer-edit]'))b.onclick=()=>Router.go('/customers?editor=customer&id='+b.dataset.customerEdit);$('contract-filter').onsubmit=e=>{e.preventDefault();Router.go('/customers?'+new URLSearchParams(new FormData(e.target)));};ProductContext.dirty=false;
 },
 async customerEditor(type,row,o,saved){
  const S=CobaltSalesUI,t=this.t,customer=type==='customer',write=S.can('customer:write'),v=saved||row;if(!row.id&&!write)throw Error(t('无编辑权限','No editing permission'));this.editor={type,row,o};
  S.page(t(customer?(row.id?'编辑客户档案':'新增客户'):(row.id?'编辑合同档案':'新增合同'),customer?(row.id?'Edit Customer Record':'Create Customer'):(row.id?'Edit Contract':'Create Contract')),`<form id="${customer?'co-customer-form':'co-contract-form'}" class="user-form"><fieldset ${write?'':'disabled'}><div class="form-grid">${customer?`<label>${t('客户名称','Customer Name')}<input name="name" required maxlength="160" value="${esc(v.name||'')}"></label><label>${t('客户代码','Customer Code')}<input name="code" required maxlength="60" value="${esc(v.code||'')}"></label><label>${t('项目','Project')}<select name="project_id" ${row.id?'disabled':''}>${o.projects.map(p=>`<option value="${p.id}" ${v.project_id===p.id?'selected':''}>${esc(I18n.translate(p.name,true))}</option>`).join('')}</select></label><label>${t('邮件','Email')}<input name="email" type="email" maxlength="320" value="${esc(v.email||'')}"></label><label>${t('联系电话','Phone')}<input name="phone" type="tel" maxlength="80" value="${esc(v.phone||'')}"></label>`:`<label>${t('客户','Customer')}<select name="customer_id" ${row.id?'disabled':''} required><option value="">${t('请选择','Select')}</option>${S.customerRows.map(c=>`<option value="${c.id}" ${c.id===v.customer_id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>${S.field('contract_no','合同号','Contract Number',v.contract_no)}${S.field('effective_date','生效日期','Effective Date',v.effective_date,'date')}${S.field('end_date','截止日期','End Date',v.end_date,'date')}`}<label>${t('状态','Status')}<select name="active"><option value="true">${t('启用','Active')}</option><option value="false" ${v.active===false?'selected':''}>${t('停用','Inactive')}</option></select></label></div>${customer?`<label>${t('地址','Address')}<textarea name="address" maxlength="1000">${esc(v.address||'')}</textarea></label>`:''}<p class="error" id="co-sales-error" role="alert"></p>${write?`<button class="button primary">${t(customer?'保存客户':'保存合同',customer?'Save Customer':'Save Contract')}</button>`:''}</fieldset><a class="button secondary" href="/customers">${t('返回客户管理','Back to Customers')}</a></form>`);
  const form=$(customer?'co-customer-form':'co-contract-form');form.onsubmit=async e=>{e.preventDefault();if(!write)return;e.submitter.disabled=true;try{const b=S.values(form);b.active=b.active==='true';if(!customer)b.project_id=S.customerRows.find(c=>c.id===b.customer_id)?.project_id;if(row.id)b.version=row.version;await API.request(S.base+(customer?'/customers':'/contracts')+(row.id?'/'+row.id:''),{method:'POST',body:b});ProductContext.dirty=false;await Router.go('/customers');notify(t(customer?'客户已保存':'合同已保存',customer?'Customer Saved':'Contract Saved'));}catch(err){$('co-sales-error').textContent=S.error(err);if(e.submitter.isConnected)e.submitter.disabled=false;}};ProductContext.dirty=false;
 },
 async stock(){
  const S=CobaltStockUI,t=this.t,q=S.q(),[d,filters]=await Promise.all([API.request('/cobalt/stock?'+q),S.filters()]),s=d.summary;
  CobaltUI.page(t('库存查询','Stock Query'),`<div class="co-stock-page ux8-stock"><section class="panel ux8-filter-panel"><div class="panel-heading"><h2>${t('筛选库存','Filter Stock')}</h2><button id="ux8-stock-reset" class="text-button">${t('重置筛选','Reset Filters')}</button></div>${filters}</section><section class="v34-kpi-grid" aria-label="${t('当前筛选结果指标','Current Filtered Stock Metrics')}">${[[t('当前库存批次数','Current Stock Batches'),s.batches],[t('当前库存袋数','Current Stock Bags'),s.bags],[t('已确认实际毛重（MT）','Confirmed Gross (MT)'),s.actual_gross_mt],[t('已确认实际净重（MT）','Confirmed Net (MT)'),s.actual_net_mt],[t('未确认实际重量袋数','Unconfirmed Weight Bags'),s.unconfirmed_bags],[t('已完成批次ARECOMS金属吨','Completed Batch ARECOMS MT'),CobaltMetal.format(s.completed_arecoms_mt||'0')]].map(([k,v])=>this.card(k,v)).join('')}</section><section class="panel detail-panel"><div class="table-toolbar"><div><h2>${t('库存明细','Stock Details')} <span class="count-chip">${d.total}</span></h2><p>${t('按备货批次汇总，点击批次查看袋级明细；实物吨与金属吨分别列示。','Grouped by preparation batch. Open a batch for bag details. Physical and metal MT are shown separately.')}</p></div><div class="export-actions"><a class="button secondary" href="/stock-map?${esc(q)}">${t('库存地图','Stock Map')}</a>${S.can('inventory:export')?`<button id="co-stock-export" class="button primary">${t('导出 Excel','Export Excel')}</button>`:''}</div></div><p id="co-stock-error" class="error" role="alert"></p>${CobaltSalesUI.table([['备货批次','Preparation Batch'],['仓库 / 货位','Warehouse / Locations'],['库存袋数 / 整批袋数','Matched / Whole Batch Bags'],['预计毛重 / 净重（MT）','Expected Gross / Net (MT)'],['已确认实际毛重 / 净重（MT）','Confirmed Gross / Net (MT)'],['未确认重量袋数','Unconfirmed Bags'],['状态','Status'],['钴品位（%）','Cobalt Grade (%)'],['整批ARECOMS金属吨','Whole Batch ARECOMS MT']],d.items.map(b=>{const detail=new URLSearchParams(q);detail.delete('page');return `<tr><td><a href="/inventory/${b.preparation_id}?${esc(detail)}">${esc(b.preparation_batch_no)}</a></td><td>${esc(I18n.translate(b.warehouse_name,true))}<br>${esc(b.location_codes?.join(', ')||t('未定位','Unlocated'))}</td><td>${b.bags} / ${b.batch_total_bags}</td><td>${CobaltLoadingUI.mt(b.expected_gross_kg)} / ${CobaltLoadingUI.mt(b.expected_net_kg)}</td><td>${esc(b.actual_gross_mt)} / ${esc(b.actual_net_mt)}</td><td>${b.unconfirmed_bags}</td><td>${S.status(b.lifecycle_state||b.status)}${b.loading_occupied_bags?'<br><span class="co-loading-badge">'+t('装车占用','Loading Occupied')+' '+b.loading_occupied_bags+'</span>':''}</td><td>${esc(b.cobalt_grade_pct||'—')}</td><td>${esc(b.arecoms_display_mt||'—')}</td></tr>`;}),'co-stock-batches')}<div class="pagination">${S.pager(d.page,d.total,50)}</div><div class="table-footnote">${t('预计重量不计入实际重量；未确认袋单独计数。ARECOMS引用整批人工值，不按袋或货位分摊。','Expected weights do not count as actual weights. Unconfirmed bags are counted separately. ARECOMS uses the manual batch value without allocation by bag or location.')}</div></section></div>`);
  S.bindFilters();S.bindPager(d);$('ux8-stock-reset').onclick=()=>Router.go('/inventory');if($('co-stock-export'))$('co-stock-export').onclick=async()=>{try{const query=new URLSearchParams(q);query.set('language',I18n.language);const r=await API.request('/cobalt/stock/export?'+query,{binary:true}),a=document.createElement('a'),url=URL.createObjectURL(r.blob);a.href=url;a.download=r.filename||'cobalt-stock.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){$('co-stock-error').textContent=S.error(e);}};ProductContext.dirty=false;
 }
};
const polishTabs=CobaltSalesUI.tabs.bind(CobaltSalesUI);CobaltSalesUI.tabs=()=>/^\/(customers|sales-plans)(\/|$)/.test(location.pathname)?'':polishTabs();
CobaltSalesUI.customers=s=>ProductPolish.customers(s);CobaltStockUI.list=()=>ProductPolish.stock();
const polishLanguage=CobaltSalesUI.language.bind(CobaltSalesUI);CobaltSalesUI.language=async()=>{if(location.pathname==='/customers'&&ProductPolish.editor&&($('co-customer-form')||$('co-contract-form'))){const f=$('co-customer-form')||$('co-contract-form'),v=CobaltSalesUI.values(f),dirty=ProductContext.dirty;v.active=v.active==='true';await ProductPolish.customerEditor(ProductPolish.editor.type,ProductPolish.editor.row,ProductPolish.editor.o,v);ProductContext.dirty=dirty;return;}return polishLanguage();};
const polishNav=CobaltSalesUI.nav.bind(CobaltSalesUI);CobaltSalesUI.nav=()=>{polishNav();ProductPolish.nav();};
const polishNormalize=CoRefinement.normalize.bind(CoRefinement);CoRefinement.normalize=()=>{polishNormalize();ProductPolish.nav();};
const polishExecutionTabs=CobaltExecutionUI.tabs.bind(CobaltExecutionUI);CobaltExecutionUI.tabs=()=>polishExecutionTabs()+(location.pathname==='/outbounds'&&CobaltUI.can('loading-plan:write')?'<a id="co-outbound-create-loading" class="button primary" href="/loading-plans/new?create_order=1">'+ProductPolish.t('新建装车单','Create Loading Order')+'</a>':'');
