Router.names['loading-plans']='装车计划管理';

// These two product-specific labels are translated by their owner, not twice by the generic observer.
const polishMount=ProductContext.mount.bind(ProductContext);ProductContext.mount=function(){polishMount();const set=I18n.set.bind(I18n);I18n.set=language=>{const r=set(language);ProductPolish.nav();return r;};ProductPolish.nav();};
